-- ============================================================================
-- The Jesus Index — consent reference for every country (migration 0058)
--
-- Extends consent_country_rules (0053) from 21 countries to 200: every UN member
-- state plus Vatican City, Palestine, Taiwan, Kosovo, Hong Kong, Macau and
-- Puerto Rico. Seeded from src/data/consent-countries.json, row for row
-- (tests/consentCountriesSeed.test.ts). The 21 rows from 0053 are untouched.
--
-- The 179 new rows are reference_version '2026-10-v2': a FIRST-PASS desk
-- reference prepared for counsel review. Where a statute, age or rule could
-- not be confirmed the row says "to confirm" or "assume", and the age defaults
-- to 18. Reference only, never legal advice.
--
-- care_level is data, and it is enforced: confirm_survey_consent (0053)
-- refuses a survey consent naming any block_until_advice country unless a
-- local-advice reference is recorded. This migration adds
-- 16 such countries (proselytism or apostasy criminalised, minors barred
-- from religious activity, or active conflict) and marks
-- 32 more as high. Change by PR, like the instrument.
-- ============================================================================

insert into public.consent_country_rules
  (country_code, country, care_level, parental_consent_under, main_law, parental_consent_note,
   faith_data, ethics_review, data_abroad, summary, reference_version) values
